    expect(await view(page, 'view.openConditionalDialog("greaterThan")')).toBe(true);
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect(await view(page, 'api.getCell(view.workbook.sheets[0], 0, 3).value')).toBe(12);
    await page.keyboard.press('Escape');
    await select(page, 'D2');
    await page.keyboard.type('=1+');
    expect(await view(page, 'view.openConditionalDialog("manage")')).toBe(false);
    await expect(message(page)).toHaveText('Finish the formula first');
    expect(await view(page, 'view.isEditing')).toBe(true);
    await page.keyboard.press('Escape');

    await view(page, 'view.addConditionalRule(api.parseRange("A1:A4"), { type: "duplicateValues", format: { fill: "#FFC7CE" } })');
    expect(await rules(page)).toEqual(['0|A1:A4|duplicateValues|1']);
    await page.evaluate(() => (window as any).__editor.setReadOnly(true));
    await expect(command(page, 'conditionalFormat')).toBeDisabled();
    expect(await view(page, 'view.openConditionalDialog("manage")')).toBe(false);
    await view(page, 'view.clearConditionalRules()');
    await view(page, 'view.removeConditionalRule(0)');
    await view(page, 'view.addConditionalRule(api.parseRange("C1"), { type: "uniqueValues" })');
