  // Fourth review: the rules after the first 200 are shown too, in runs of 200 (they could not be reached before).
  test('a sheet with very many rules: the list shows 200 of them at a time and says which', async ({ page }) => {
    let rulesXml = '';
    for (let i = 1; i <= 20000; i++) rulesXml += `<cfRule type="cellIs" priority="${i}" operator="equal"><formula>${i}</formula></cfRule>`;
    const bytes = await buildXlsx({ sheets: [{ name: 'Data', xml: worksheetXml(`${CELLS}<conditionalFormatting sqref="A1:A4">${rulesXml}</conditionalFormatting>`) }], styles: STYLES });
    await mount(page, bytes);
    expect(await view(page, 'view.openConditionalDialog("manage")')).toBe(true);
    await field(page, 'scope', 'conditional-rules').selectOption('sheet');
    const shown = () => manager(page).locator('[data-bym-rule]').count();
    expect(await shown()).toBe(200);
    await expect(manager(page).locator('[data-bym-field="more"]')).toHaveText('Rules 1 to 200 of 20000');
    // A change builds the same bounded list again.
    await row(page, 0).locator('[data-bym-action="delete"]').click();
    expect(await shown()).toBe(200);
    await expect(manager(page).locator('[data-bym-field="more"]')).toHaveText('Rules 1 to 200 of 19999');
    await expect(row(page, 0).locator('.bym-dialog-rule-text')).toHaveText('Cell value equal to 2');
    // The rows, the line that says which they are, and the buttons to the other runs.
    expect(await manager(page).locator('.bym-dialog-rules > *').count()).toBeLessThanOrEqual(202);
    await action(page, 'next-page', 'conditional-rules').click();
    expect(await shown()).toBe(200);
    await expect(manager(page).locator('[data-bym-field="more"]')).toHaveText('Rules 201 to 400 of 19999');
    await expect(row(page, 0).locator('.bym-dialog-rule-text')).toHaveText('Cell value equal to 202');
    await page.keyboard.press('Escape');
  });

  test('a data bar of Excel 2010: what it says is kept, its cells can be changed, and it can be deleted - with its other half', async ({ page }) => {
    const bytes = await conditionalBook({ extensionOnly: false, otherExt: true });
    await mount(page, bytes);
    expect(await view(page, 'view.openConditionalDialog("manage")')).toBe(true);
    await field(page, 'scope', 'conditional-rules').selectOption('sheet');
    expect((await rowTexts(page))[3]).toBe('Data bar');
    await expect(row(page, 3).locator('[data-bym-action="edit"]')).toBeDisabled();
    await expect(row(page, 3).locator('[data-bym-action="edit"]')).toHaveAttribute('title', /newer Excel/);
    await expect(row(page, 3).locator('[data-bym-action="delete"]')).toBeEnabled();
    const cells = row(page, 3).locator('[data-bym-field="ranges"]');
    await cells.fill('C2:C4');
    await cells.press('Enter');
    await expect(alert(page, 'conditional-rules')).toHaveText('');
    const halves = () =>
      page.evaluate(async () => {
        const text = new TextDecoder().decode(await (window as any).BymOffice.ZipArchive.read((await (window as any).__file.save()) as Uint8Array).read('xl/worksheets/sheet1.xml'));
        return [/<conditionalFormatting sqref="C2:C4"><cfRule type="dataBar"/.test(text), /<xm:sqref>C2:C4<\/xm:sqref>/.test(text), text.includes('DA7ABA51-AAAA-BBBB-0001-000000000001'), text.includes('sparklineGroups')];
      });
    expect(await halves()).toEqual([true, true, true, true]);
    await row(page, 3).locator('[data-bym-action="delete"]').click();
    expect(await rowTexts(page)).not.toContain('Data bar');
    expect(await halves()).toEqual([false, false, false, true]);
    await page.keyboard.press('Escape');
    await page.evaluate(() => {
      const view = (window as any).__editor.view;
      while (view.history.canUndo) view.undo();
    });
    expect(await page.evaluate(async () => Array.from((await (window as any).__file.save()) as Uint8Array))).toEqual(Array.from(bytes));
  });
